// Owning domain : Payments (chora_payments DB, per ADR-164).
// Topic prefix  : chora.payments.companion_egg_purchase.*
//
// Replaces (post Wave 1 Stage D cutover):
//   chora.tenancy.companion_egg.checkout_started.v1
//   chora.tenancy.companion_egg.payment_succeeded.v1
//   chora.tenancy.companion_egg.payment_failed.v1
//   chora.tenancy.companion_egg.refunded.v1
//   (no expired counterpart in the legacy family — added here for parity)
